/**
 * Historia & humaniora → Historiska epoker → Revolutioner & industrialisering, 1941–1947 (0.36): the
 * Enlightenment, the American and French revolutions, industrial factories, the labour movement, the
 * transformation of nations and 19th-century urbanisation. Shared signs: 1700s figures with white wigs and
 * long coats, tricorne hats, parchment documents with lines (never letters), red banners for the labour
 * movement, brick factories with smoking chimneys, steam machines, and simple maps with a highlighted part.
 * No letters that give the word away, no pointing fingers; a grey reference stands beside the coloured
 * thing where a contrast helps.
 */
import { C, all, arrow, circle, ellipse, g, line, path, rect, sparkle, star, type Svg } from './kit';
import { type Build } from './figures';
import { HL, arm, heart, note } from './people';
import { P as F, type Mood, greyed } from './blindFix';

// ── Colours and geometry ─────────────────────────────────────────────
const BRICK = '#b5543c';
const BRICK2 = '#8e3f2c';
const SOOT = '#4a4a52';
const SMOKE = '#9a9aa2';
const PARCH = '#f3e3b8';
const WOOD = '#a0673d';
const IRON = '#5b6270';
const COAT_R = '#b8322a';
const COAT_B = '#2f4f8f';
const FR_B = '#2c4fa0';
const LAND = '#d9c58f';
const SEA = '#9fd0ec';
const RED = '#c62f2f';
const f1 = (n: number) => n.toFixed(1);
const ground = line('M4 112 L116 112', C.grey2, 2);
/** Head and shoulder positions of a standing figure at x with height factor h. */
const geo = (x: number, h = 1) => { const s = 0.84 * h, ty = 112 - 49 * s; return { s, ty, hy: ty - 56 * s, hr: 10 * s, sy: ty - 38 * s, sl: x - 13 * s, sr: x + 13 * s }; };
/** An arm from the shoulder (side −1 = picture-left) to a hand at (tx, ty). */
const reach = (x: number, h: number, side: -1 | 1, tx: number, ty: number) => { const q = geo(x, h); return all(arm(side < 0 ? q.sl : q.sr, q.sy, tx, ty), circle(tx, ty, 3 * Math.max(0.6, h), C.skin, C.ink, 1.2)); };
type Face = Mood | 'flat';
const fig = (x: number, top: string, mood: Face = 'smile', more: Partial<Build> = {}) => (mood === 'flat' ? F({ x, top, face: 'neutral', ...more }) : F({ x, top, mood, ...more }));
/** Draw in the local coordinates of the standing figure at x (head centre 0,−56; torso −42…2; feet at 49). */
const on = (x: number, h: number, ...k: Svg[]) => { const s = 0.84 * h; return g(`translate(${x} ${f1(112 - 49 * s)}) scale(${s.toFixed(3)})`, ...k); };

// ── Clothes and head wear (figure coordinates) ───────────────────────
/** White 1700s wig: curls beside the ears and a ribbon at the back. */
const wig = all(path('M-9 -60 C-9 -68 9 -68 9 -60 C6 -63 -6 -63 -9 -60 Z', C.white, C.ink, 1), ...[-1, 1].map((d) => all(ellipse(d * 9.5, -55, 2.6, 2.2, C.white, C.ink, 0.9), ellipse(d * 9.5, -50.5, 2.6, 2.2, C.white, C.ink, 0.9))));
/** Long coat with buttons over the torso and a white cravat. */
const coat = (col: string) => all(path('M-14 -42 L14 -42 C15 -24 16 -4 17 14 L-17 14 C-16 -4 -15 -24 -14 -42 Z', col, C.ink, 2), line('M0 -40 L0 12', C.ink, 1), ...[-34, -26, -18, -10].map((y) => circle(3, y, 1.2, C.gold, C.ink, 0.6)), path('M-4 -42 L4 -42 L2 -34 L-2 -34 Z', C.white, C.ink, 0.9));
const tricorne = (col: string = C.black) => path('M-14 -62 C-8 -70 8 -70 14 -62 C8 -66 4 -76 0 -74 C-4 -76 -8 -66 -14 -62 Z', col, C.ink, 1.2);
const tophat = (col: string = C.black) => all(rect(-8, -80, 16, 17, col, 1, C.ink, 1.2), rect(-13, -65, 26, 3.4, col, 1.5, C.ink, 1.2), rect(-8, -68, 16, 2.4, RED, 0, null));
/** Flat worker's cap. */
const cap = (col: string = '#6b5a4a') => all(path('M-10 -60 C-10 -70 10 -70 10 -60 Z', col, C.ink, 1.2), path('M2 -61 L16 -60 L14 -58 L2 -59 Z', col, C.ink, 1));
const apron = (col: string = '#d8cdb8') => path('M-9 -30 L9 -30 L11 10 L-11 10 Z', col, C.ink, 1.2);
const patch = (x: number, y: number) => all(rect(x, y, 6, 6, '#c9b07a', 0.5, C.ink, 0.8), line(`M${x + 1} ${y + 1} l4 4 M${x + 5} ${y + 1} l-4 4`, C.ink, 0.5));
/** Long dress over the legs. */
const gown = (col: string) => all(path('M-13 -42 L13 -42 L14 -8 C20 10 24 30 26 48 L-26 48 C-24 30 -20 10 -14 -8 Z', col, C.ink, 2), path('M-13 -42 L13 -42 L12 -30 L-12 -30 Z', C.white, C.ink, 1));
const hairBun = path('M-9 -60 C-9 -70 9 -70 9 -60 C6 -64 -6 -64 -9 -60 Z M-3 -71 a4 4 0 1 0 6 0', '#c9b08a', C.ink, 1);
const miniCrown = (x: number, y: number, s = 1) => g(`translate(${x} ${y}) scale(${s})`, path('M-6 -12 L-6 -19 L-3 -15.5 L0 -21 L3 -15.5 L6 -19 L6 -12 Z', C.gold, C.ink, 1));
/** Small head-and-shoulders person; (x, y) = head centre. */
const mini = (x: number, y: number, col: string, mood: 'smile' | 'frown' | 'flat' | 'shock' | 'angry' = 'smile', s = 1, grey = false) => { const sk = grey ? C.grey2 : C.skin, hr = grey ? C.grey : C.hair, c = grey ? C.grey : col; return g(`translate(${x} ${y}) scale(${s})`, path('M-10 16 C-10 4 10 4 10 16 Z', c, C.ink, 1.4), circle(0, -6, 7.5, sk, C.ink, 1.4), path('M-7.5 -8 C-7.5 -16 7.5 -16 7.5 -8 C4 -11 -4 -11 -7.5 -8 Z', hr, null),
  mood === 'shock' ? all(circle(-2.6, -6, 1.4, C.white, C.ink, 0.7), circle(2.6, -6, 1.4, C.white, C.ink, 0.7), ellipse(0, -1.8, 1.2, 1.5, '#c84a4a', C.ink, 0.6)) : all(circle(-2.6, -6, 1, C.ink, null), circle(2.6, -6, 1, C.ink, null)),
  mood === 'angry' ? line('M-4.6 -9.6 L-1.2 -8.2 M4.6 -9.6 L1.2 -8.2', C.ink, 1) : '',
  mood === 'smile' ? path('M-2.6 -2.6 Q0 -0.6 2.6 -2.6', 'none', C.ink, 1.1) : mood === 'flat' ? line('M-2.4 -2 L2.4 -2', C.ink, 1.1) : mood === 'frown' || mood === 'angry' ? path('M-2.6 -1.4 Q0 -3.4 2.6 -1.4', 'none', C.ink, 1.1) : ''); };
const COLS = [C.orange, C.green, C.sky, C.pink, C.yellow, C.purple];
const crowd = (x: number, y: number, n: number, cols: string[] = COLS, s = 0.8, gap = 12, mood: 'smile' | 'frown' | 'flat' | 'shock' | 'angry' = 'smile') => all(...Array.from({ length: n }, (_, i) => mini(x + i * gap, y + (i % 2) * 3, cols[i % cols.length]!, mood, s)));
const greyCrowd = (x: number, y: number, n: number, s = 0.7, gap = 11, mood: 'smile' | 'frown' | 'flat' | 'shock' = 'flat') => all(...Array.from({ length: n }, (_, i) => mini(x + i * gap, y + (i % 2) * 3, C.grey, mood, s, true)));
/** A raised hand (palm forward) at (x, y), arm going down. */
const raised = (x: number, y: number, s = 1) => g(`translate(${x} ${y}) scale(${s})`, line('M0 6 L0 16', C.skin, 4), ...[-4.8, -2.2, 0.4, 3].map((fx, i) => rect(fx, i === 0 || i === 3 ? -7.5 : -9, 2.4, 9, C.skin, 1.2, C.ink, 0.8)), path('M-5 -1 L5.4 -1 L5.4 6 C5.4 9 -5 9 -5 6 Z', C.skin, C.ink, 1));
/** Speech bubble at (cx, cy) with a tail to (tx, ty). */
const say = (cx: number, cy: number, w: number, h: number, tx: number, ty: number, inner: Svg = '') => {
  const L = cx - w / 2, R = cx + w / 2, Tp = cy - h / 2, B = cy + h / 2; let a: number[], b: number[];
  if (tx < L || tx > R) { const e = tx < L ? L : R, by = Math.max(Tp + 5, Math.min(B - 5, ty)); a = [e, by - 4]; b = [e, by + 4]; }
  else { const e = ty > cy ? B : Tp, bx = Math.max(L + 6, Math.min(R - 6, tx)); a = [bx - 4, e]; b = [bx + 4, e]; }
  return all(path(`M${a[0]} ${a[1]} L${tx} ${ty} L${b[0]} ${b[1]} Z`, C.white, C.ink, 1.4), rect(L, Tp, w, h, C.white, 5, C.ink, 1.4), path(`M${a[0]} ${a[1]} L${tx} ${ty} L${b[0]} ${b[1]} Z`, C.white, null), inner);
};
const lines = (x: number, y: number, w: number, n: number, gap = 4, col: string = C.grey) => all(...Array.from({ length: n }, (_, i) => line(`M${x} ${y + i * gap} L${x + (i === n - 1 ? w * 0.6 : w)} ${y + i * gap}`, col, 1.6)));
const think = (cx: number, cy: number, r: number, tx: number, ty: number, inner: Svg = '') => all(circle(tx, ty, 1.6, C.white, C.ink, 1), circle((tx + cx) / 2, (ty + cy + r) / 2, 2.6, C.white, C.ink, 1.1), ellipse(cx, cy, r * 1.2, r, C.white, C.ink, 1.4), inner);

// ── Things ───────────────────────────────────────────────────────────
const book = (x: number, y: number, w: number, h: number, col: string, band = C.gold) => all(rect(x, y, w, h, col, 1, C.ink, 1.2), line(`M${x + 1.5} ${y + 4} L${x + w - 1.5} ${y + 4} M${x + 1.5} ${y + h - 4} L${x + w - 1.5} ${y + h - 4}`, band, 1.2));
const openBook = (x: number, y: number, s = 1) => g(`translate(${x} ${y}) scale(${s})`, path('M0 -2 C-8 -8 -20 -8 -28 -4 L-28 16 C-20 12 -8 12 0 18 C8 12 20 12 28 16 L28 -4 C20 -8 8 -8 0 -2 Z', C.white, C.ink, 1.6), line('M0 -2 L0 18', C.ink, 1.2), lines(-24, 0, 18, 4, 3.6), lines(6, 0, 18, 4, 3.6));
/** Parchment document with lines and signatures. */
const parchment = (x: number, y: number, w: number, h: number, sigs = 0) => all(rect(x, y, w, h, PARCH, 2, C.ink, 1.4), ellipse(x + w / 2, y, w / 2 + 2, 3, '#e6cf98', C.ink, 1.1), ellipse(x + w / 2, y + h, w / 2 + 2, 3, '#e6cf98', C.ink, 1.1), lines(x + 6, y + 8, w - 12, Math.max(2, Math.floor((h - 16 - sigs * 3) / 5)), 5, '#8a6a3a'),
  ...Array.from({ length: sigs }, (_, i) => path(`M${x + 6 + (i % 3) * ((w - 12) / 3)} ${y + h - 6 - Math.floor(i / 3) * 6} q3 -4 5 0 q2 3 4 -1 q2 -3 4 0`, 'none', C.navy, 1)));
const quill = (x: number, y: number, s = 1) => g(`translate(${x} ${y}) scale(${s})`, path('M0 0 C4 -10 12 -22 20 -28 C16 -18 10 -8 2 1 Z', C.white, C.ink, 1.1), line('M0 0 L-3 5', C.ink, 1.4), line('M2 -2 L16 -24', C.grey, 0.8));
const inkpot = (x: number, y: number) => all(rect(x - 6, y - 8, 12, 8, C.dark, 2, C.ink, 1.2), rect(x - 3, y - 11, 6, 3, C.dark, 1, C.ink, 1));
const coin = (x: number, y: number, r = 4.5) => all(circle(x, y, r, C.gold, C.ink, 1.1), circle(x, y, r * 0.55, 'none', '#b88a20', 0.9));
const smoke = (x: number, y: number, s = 1, col: string = SMOKE) => g(`translate(${x} ${y}) scale(${s})`, circle(0, 0, 5, col, null), circle(6, -6, 6.5, col, null), circle(14, -10, 7.5, col, null), circle(24, -12, 8, col, null));
/** Brick factory with saw-tooth roof and chimneys; (x, y) = bottom-left, w wide. */
const factory = (x: number, y: number, w: number, h: number, chimneys = 2, puff = true) => {
  const n = Math.max(2, Math.round(w / 18)), tw = w / n;
  return all(
    ...Array.from({ length: chimneys }, (_, i) => { const cx = x + w * (0.25 + i * 0.4); return all(puff ? smoke(cx + 2, y - h - 30, 0.8) : '', rect(cx - 4, y - h - 26, 8, 26, BRICK2, 0, C.ink, 1.3), rect(cx - 5, y - h - 28, 10, 3, SOOT, 0, C.ink, 1)); }),
    rect(x, y - h, w, h, BRICK, 0, C.ink, 1.5),
    path(Array.from({ length: n }, (_, i) => `M${f1(x + i * tw)} ${y - h} L${f1(x + i * tw)} ${y - h - 9} L${f1(x + (i + 1) * tw)} ${y - h}`).join(' '), '#cfd5db', C.ink, 1.3),
    ...Array.from({ length: n }, (_, i) => rect(x + i * tw + tw / 2 - 3.5, y - h + 6, 7, 9, '#f6dd8a', 0.5, C.ink, 1)),
    line(Array.from({ length: Math.floor(h / 6) }, (_, i) => `M${x} ${y - h + 4 + i * 6} L${x + w} ${y - h + 4 + i * 6}`).join(' '), BRICK2, 0.5));
};
/** A spinning frame: rows of bobbins with threads; (x, y) = bottom-left. */
const spinFrame = (x: number, y: number, w: number, s = 1) => g(`translate(${x} ${y}) scale(${s})`, rect(0, -6, w, 6, WOOD, 0, C.ink, 1.2), rect(0, -40, w, 4, WOOD, 0, C.ink, 1.2), line(`M2 -6 L2 -40 M${w - 2} -6 L${w - 2} -40`, WOOD, 3),
  ...Array.from({ length: Math.floor(w / 8) }, (_, i) => { const bx = 6 + i * 8; return all(line(`M${bx} -36 L${bx} -16`, '#f6f2ea', 0.9), ellipse(bx, -12, 2.6, 5, C.white, C.ink, 0.9), ellipse(bx, -30, 2.2, 3, '#e8d9b8', C.ink, 0.8)); }));
/** Steam engine: boiler, cylinder, rod and flywheel; (x, y) = floor point at the left. */
const steamEngine = (x: number, y: number, s = 1, puff = true) => g(`translate(${x} ${y}) scale(${s})`,
  rect(0, -34, 40, 30, IRON, 6, C.ink, 1.6), ...[8, 20, 32].map((rx) => line(`M${rx} -34 L${rx} -4`, '#4a505c', 1)), rect(10, -46, 6, 12, SOOT, 0, C.ink, 1.2), puff ? smoke(14, -52, 0.6, C.white) : '',
  rect(40, -26, 18, 12, '#8a929e', 2, C.ink, 1.4), line('M58 -20 L80 -30', C.ink, 3), circle(84, -30, 22, 'none', C.ink, 3.2), circle(84, -30, 22, 'none', IRON, 2), ...[0, 1, 2, 3].map((i) => { const a = (i * Math.PI) / 4; return line(`M${f1(84 - Math.cos(a) * 20)} ${f1(-30 - Math.sin(a) * 20)} L${f1(84 + Math.cos(a) * 20)} ${f1(-30 + Math.sin(a) * 20)}`, IRON, 2); }), circle(84, -30, 4, C.gold, C.ink, 1.2),
  rect(-2, -4, 108, 4, '#7a6a5a', 0, C.ink, 1.2), path('M76 -4 L84 -30 L92 -4 Z', 'none', C.ink, 1.6));
/** Steam locomotive facing right; (x, y) = rail level at the back. */
const loco = (x: number, y: number, s = 1, puff = true) => g(`translate(${x} ${y}) scale(${s})`,
  puff ? all(smoke(54, -50, 0.9, '#6e6e76'), smoke(66, -60, 0.7, SMOKE)) : '', rect(0, -40, 22, 28, COAT_R, 2, C.ink, 1.6), rect(3, -36, 16, 10, '#f6dd8a', 1, C.ink, 1), rect(-3, -44, 28, 5, SOOT, 1, C.ink, 1.3),
  rect(22, -30, 38, 18, SOOT, 8, C.ink, 1.6), rect(48, -44, 8, 14, SOOT, 0, C.ink, 1.3), path('M46 -46 L58 -46 L56 -43 L48 -43 Z', SOOT, C.ink, 1.2), rect(32, -36, 8, 6, C.gold, 3, C.ink, 1), path('M60 -16 L68 -8 L60 -8 Z', IRON, C.ink, 1.2),
  rect(-2, -14, 64, 4, C.ink, 0, null), ...[10, 30].map((wx) => all(circle(wx, -6, 8, C.red, C.ink, 1.6), circle(wx, -6, 2.4, C.ink, null))), circle(50, -5, 5, C.red, C.ink, 1.4), line('M10 -6 L50 -5', C.ink, 1.8));
const rails = (y: number, x1 = 4, x2 = 116) => all(line(`M${x1} ${y} L${x2} ${y}`, IRON, 2.2), line(Array.from({ length: Math.floor((x2 - x1) / 10) }, (_, i) => `M${x1 + 4 + i * 10} ${y + 1} L${x1 + 2 + i * 10} ${y + 5}`).join(' '), WOOD, 2));
const coalLumps = (x: number, y: number, n: number, s = 1) => all(...Array.from({ length: n }, (_, i) => { const r = (i * 37) % 5, cx = x + (i % 5) * 7 * s + (Math.floor(i / 5) % 2) * 3.5 * s, cy = y - Math.floor(i / 5) * 6 * s; return path(`M${f1(cx - 4 * s)} ${f1(cy)} L${f1(cx - 3 * s)} ${f1(cy - (4 + r * 0.4) * s)} L${f1(cx + 1 * s)} ${f1(cy - (6 + r * 0.3) * s)} L${f1(cx + 4 * s)} ${f1(cy - 3 * s)} L${f1(cx + 3.6 * s)} ${f1(cy)} Z`, '#2a2a30', C.ink, 0.8); }), ...Array.from({ length: Math.ceil(n / 3) }, (_, i) => sparkle(x + 4 + i * 9 * s, y - 4 - (i % 2) * 5, 1.2, '#8f95a3')));
/** A clock face with hands at (h, m). */
const clock = (x: number, y: number, r: number, hh = 3, mm = 0, face: string = C.white) => all(circle(x, y, r, face, C.ink, 1.6), ...Array.from({ length: 12 }, (_, i) => { const a = (i / 12) * Math.PI * 2; return line(`M${f1(x + Math.sin(a) * r * 0.82)} ${f1(y - Math.cos(a) * r * 0.82)} L${f1(x + Math.sin(a) * r * 0.92)} ${f1(y - Math.cos(a) * r * 0.92)}`, C.ink, 1); }),
  line(`M${x} ${y} L${f1(x + Math.sin((hh / 12) * Math.PI * 2) * r * 0.5)} ${f1(y - Math.cos((hh / 12) * Math.PI * 2) * r * 0.5)}`, C.ink, 2), line(`M${x} ${y} L${f1(x + Math.sin((mm / 60) * Math.PI * 2) * r * 0.75)} ${f1(y - Math.cos((mm / 60) * Math.PI * 2) * r * 0.75)}`, C.ink, 1.4), circle(x, y, 1.4, C.ink, null));
/** Pie sector of a circle from angle a0 to a1 (radians, 0 = up, clockwise). */
const sector = (x: number, y: number, r: number, a0: number, a1: number, col: string) => path(`M${x} ${y} L${f1(x + Math.sin(a0) * r)} ${f1(y - Math.cos(a0) * r)} A${r} ${r} 0 ${a1 - a0 > Math.PI ? 1 : 0} 1 ${f1(x + Math.sin(a1) * r)} ${f1(y - Math.cos(a1) * r)} Z`, col, C.ink, 1.3);
const sunIcon = (x: number, y: number, r = 4) => all(...Array.from({ length: 8 }, (_, i) => { const a = (i / 8) * Math.PI * 2; return line(`M${f1(x + Math.cos(a) * (r + 1.5))} ${f1(y + Math.sin(a) * (r + 1.5))} L${f1(x + Math.cos(a) * (r + 4))} ${f1(y + Math.sin(a) * (r + 4))}`, C.gold, 1.4); }), circle(x, y, r, C.yellow, C.ink, 1.1));
const moonIcon = (x: number, y: number, r = 5) => path(`M${x + r * 0.3} ${y - r} A${r} ${r} 0 1 0 ${x + r * 0.3} ${y + r} A${r * 0.75} ${r * 0.75} 0 1 1 ${x + r * 0.3} ${y - r} Z`, '#f2e6a0', C.ink, 1.1);
const flag = (x: number, y: number, s: number, cloth: Svg, pole = 30) => g(`translate(${x} ${y}) scale(${s})`, line(`M0 0 L0 ${-pole}`, C.brown, 2), g(`translate(0 ${-pole})`, cloth));
const banner = (col: string = RED) => all(path('M0 0 L26 0 C22 6 26 12 26 16 L0 16 Z', col, C.ink, 1.3));
const triFR = all(rect(0, 0, 9, 16, FR_B, 0, C.ink, 1), rect(9, 0, 9, 16, C.white, 0, C.ink, 1), rect(18, 0, 9, 16, RED, 0, C.ink, 1));
const starsStripes = all(rect(0, 0, 28, 17, C.white, 0, C.ink, 1), ...[0, 2, 4, 6].map((i) => rect(0, i * 2.4 + 0.1, 28, 2.4, RED, 0, null)), rect(0, 0, 12, 9, COAT_B, 0, null), ...[0, 1, 2].flatMap((i) => [0, 1].map((j) => circle(2.5 + i * 3.5, 2.5 + j * 4, 0.8, C.white, null))), rect(0, 0, 28, 17, 'none', 0, C.ink, 1));
/** Crown symbol. */
const crown = (x: number, y: number, s = 1, col: string = C.gold) => g(`translate(${x} ${y}) scale(${s})`, path('M-10 4 L-10 -6 L-5 -1 L0 -9 L5 -1 L10 -6 L10 4 Z', col, C.ink, 1.3), circle(0, -9, 1.6, RED, C.ink, 0.6));
const house = (x: number, y: number, w: number, h: number, wall: string, roof: string, door = true) => all(rect(x, y - h, w, h, wall, 0, C.ink, 1.4), path(`M${x - 3} ${y - h} L${x + w / 2} ${y - h - w * 0.45} L${x + w + 3} ${y - h} Z`, roof, C.ink, 1.4), door ? rect(x + w / 2 - 3, y - 10, 6, 10, WOOD, 0.5, C.ink, 1) : '');
const field = (x: number, y: number, w: number, h: number) => all(rect(x, y, w, h, '#d8c36a', 0, C.ink, 1), line(Array.from({ length: Math.floor(w / 6) }, (_, i) => `M${x + 3 + i * 6} ${y + h - 1} l2 ${-h + 2}`).join(' '), '#b39a3e', 1));
